#include "stdlib/blas/base/sgemv.h"
#include "stdlib/blas/base/sgemv_cblas.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/min_view_buffer_index.h"
#include "stdlib/ndarray/base/min_view_buffer_index.h"

/**
* Performs one of the matrix-vector operations `Y = α*A*X + β*Y` or `Y = α*A^T*X + β*Y`, where `α` and `β` are scalars, `X` and `Y` are vectors, and `A` is an `M` by `N` matrix.
*
* @param order    storage layout
* @param trans    specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param M        number of rows in the matrix `A`
* @param N        number of columns in the matrix `A`
* @param alpha    scalar constant
* @param A        input matrix
* @param LDA      stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param X        first input vector
* @param strideX  `X` stride length
* @param beta     scalar constant
* @param Y        second input vector
* @param strideY  `Y` stride length
* @return         output value
*/
float API_SUFFIX(c_sgemv)( const CBLAS_LAYOUT order, const CBLAS_TRANSPOSE trans, const CBLAS_INT M, const CBLAS_INT N, const float alpha, const float *A, const CBLAS_INT LDA, const float *X, const CBLAS_INT strideX, const float beta, const float *Y, const CBLAS_INT strideY ) {
	CBLAS_INT sx = strideX;
	CBLAS_INT sy = strideY;
	if ( sx < 0 ) {
		sx = -sx;
	}
	if ( sy < 0 ) {
		sy = -sy;
	}
	return API_SUFFIX(cblas_sgemv)( order, trans, M, N, alpha, A, LDA, X, sx, beta, Y, sy );
}

/**
* Performs one of the matrix-vector operations `Y = α*A*X + β*Y` or `Y = α*A^T*X + β*Y` using alternative indexing semantics, where `α` and `β` are scalars, `X` and `Y` are vectors, and `A` is an `M` by `N` matrix.
*
* @param trans     specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param M         number of rows in the matrix `A`
* @param N         number of columns in the matrix `A`
* @param alpha     scalar constant
* @param A         input matrix
* @param strideA1  stride of the first dimension of `A`
* @param strideA1  stride of the second dimension of `A`
* @param offsetA   starting index for `A`
* @param X         first input vector
* @param strideX   `X` stride length
* @param offsetX   starting index for `X`
* @param beta      scalar constant
* @param Y         second input vector
* @param strideY   `Y` stride length
* @param offsetY   starting index for `Y`
* @return          output value
*/
float API_SUFFIX(c_sgemv_ndarray)( const CBLAS_TRANSPOSE trans, const CBLAS_INT M, const CBLAS_INT N, const float alpha, const float *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const float beta, const float *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT sx = strideX;
	CBLAS_INT sy = strideY;
	if ( sx < 0 ) {
		sx = -sx;
	}
	if ( sy < 0 ) {
		sy = -sy;
	}
	X += stdlib_strided_min_view_buffer_index( N, strideX, offsetX ); // adjust array pointer
	Y += stdlib_strided_min_view_buffer_index( N, strideY, offsetY ); // adjust array pointer
	const int64_t shape[] = { M, N };
	const int64_t strides[] = { strideA1, strideA2 };
	A += stdlib_ndarray_min_view_buffer_index( 2, shape, strides, offsetA ); // adjust array pointer
	return API_SUFFIX(cblas_sgemv)( order, trans, M, N, alpha, A, LDA, X, sx, beta, Y, sy );
}
